render_chart <- function(data, cfg, manifest) { chart_validate_columns(data, list(x = cfg$x, y = cfg$y), c("x", "y")); p <- ggplot2::ggplot(data, ggplot2::aes_string(x = cfg$y, y = cfg$x, fill = cfg$x)) + ggridges::geom_density_ridges(alpha = 0.65, scale = 1.4, rel_min_height = 0.01) + ggplot2::theme_minimal(base_size = 12) + ggplot2::theme(legend.position = "none") + ggplot2::labs(title = cfg$title %||% NULL, x = cfg$y, y = cfg$x); chart_open_device(cfg$outputPath, cfg$format); print(p); grDevices::dev.off(); cfg$outputPath }
